function getCleanSectionLetter(secStr) {
    if (!secStr) return '';
    const m = secStr.toString().match(/\b([A-D])\b/i);
    if (m) return m[1].toUpperCase();
    const clean = secStr.toString().replace(/SECCI[OÓ]N/ig, '').trim().toUpperCase();
    const lastChar = clean.slice(-1);
    if (['A', 'B', 'C', 'D'].includes(lastChar)) return lastChar;
    return '';
}

function formatDateForInput(dateStr) {
    if (!dateStr) return '';
    if (dateStr.includes('/')) {
        const parts = dateStr.split('/');
        if (parts.length === 3) {
            const day = parts[0].padStart(2, '0');
            const month = parts[1].padStart(2, '0');
            const year = parts[2];
            return `${year}-${month}-${day}`;
        }
    }
    return dateStr;
}

function formatDateForDisplay(dateStr) {
    if (!dateStr) return '';
    if (dateStr.includes('-')) {
        const parts = dateStr.split('-');
        if (parts.length === 3) {
            const year = parts[0];
            const month = parts[1].padStart(2, '0');
            const day = parts[2].padStart(2, '0');
            return `${day}/${month}/${year}`;
        }
    }
    return dateStr;
}

function ensureSireOfficialStudents() {
    if (!Array.isArray(STATE.students) || STATE.students.length < 400) {
        STATE.students = JSON.parse(JSON.stringify(OFFICIAL_SIRE_412_STUDENTS));
    }
}

function normalizeCareers() {
    if (!Array.isArray(STATE.careers) || STATE.careers.length === 0) {
        STATE.careers = (typeof getInitialData === 'function' && getInitialData().careers) || [
            { id: 'car-01', name: 'Perito Contador', code: 'PC', duration: '3 años', status: 'Activa' },
            { id: 'car-02', name: 'Perito en Administración de Empresas', code: 'AE', duration: '3 años', status: 'Activa' },
            { id: 'car-03', name: 'Bachillerato en Ciencias y Letras', code: 'BCL', duration: '2 años', status: 'Activa' },
            { id: 'car-04', name: 'Secretariado Bilingüe', code: 'SB', duration: '2 años', status: 'Activa' }
        ];
    }
}

function updateGradeSelects() {
    const grades = STATE.gradesList || [];
    const gradeOptions = grades.map(g => `<option value="${g.code || g.name}">${g.name} (${g.section}) - ${g.career || ''}</option>`).join('');

    const selects = [
        'studentGradeFilterSelect',
        'attendanceGradeSelect',
        'pensumSubjectGrade',
        'classAssignmentGradeSelect',
        'gradeFilterSelect',
        'reportGradeSelect',
        'honorRollGradeSelect',
        'discGradeSelect'
    ];

    selects.forEach(id => {
        const el = document.getElementById(id);
        if (el) {
            const curVal = el.value;
            const isFilter = id.includes('Filter') || id.includes('Select');
            el.innerHTML = (isFilter ? '<option value="ALL">-- Todos los Grados y Secciones --</option>' : '<option value="">-- Seleccione Grado --</option>') + gradeOptions;
            if (curVal && Array.from(el.options || []).some(o => o.value === curVal)) {
                el.value = curVal;
            }
        }
    });

    if (typeof updateGradeFilterSelects === 'function') {
        try { updateGradeFilterSelects(); } catch(e) {}
    }
}

function updateCareerSelects() {
    if (typeof normalizeCareers === 'function') normalizeCareers();
    const careers = STATE.careers || [];
    const careerOptions = careers.map(c => `<option value="${c.name}">${c.name}</option>`).join('');

    const selects = [
        'gradesCareerFilter',
        'pensumCatalogCareerFilter',
        'studentCareerFilterSelect',
        'gradeModalCareer',
        'pensumSubjectCareer',
        'pensumSubjectFormCareer',
        'printModelCareerSelect',
        'careerFilterSelect'
    ];

    selects.forEach(id => {
        const el = document.getElementById(id);
        if (el) {
            const curVal = el.value;
            const isFilter = id.includes('Filter') || id.includes('Select');
            el.innerHTML = (isFilter ? '<option value="ALL">Todas las Carreras</option>' : '<option value="">-- Seleccione Carrera --</option>') + careerOptions;
            if (curVal && Array.from(el.options || []).some(o => o.value === curVal)) {
                el.value = curVal;
            } else if (isFilter) {
                el.value = 'ALL';
            }
        }
    });

    if (typeof updateCareerSelectOptions === 'function') {
        try { updateCareerSelectOptions(); } catch(e) {}
    }
}

function sortGrades(list) {
    if (!Array.isArray(list)) return [];
    return [...list].sort((a, b) => {
        const nameA = (a.name || a.code || '').toLowerCase();
        const nameB = (b.name || b.code || '').toLowerCase();
        const secA = (a.section || '').toLowerCase();
        const secB = (b.section || '').toLowerCase();
        if (nameA !== nameB) return nameA.localeCompare(nameB);
        return secA.localeCompare(secB);
    });
}

// Helper universal infalible para abrir cualquier modal
function showModalById(modalId) {
    const modal = document.getElementById(modalId);
    if (modal) {
        modal.classList.add('active');
        modal.style.setProperty('display', 'flex', 'important');
    }
}


function generateTeacherPassword(name) {
    if (!name) return 'Docente1';
    let cleaned = (name || '').replace(/^(PEM\.|LICDA\.|LIC\.|PROF\.|PROFA\.|ING\.|ARQ\.|LIC\.MA\.|LIC\. MA\.|M\.A\.)\s*/i, '').trim();
    cleaned = cleaned.replace(/^(MA\.|M\.A\.)\s*/i, '').trim();
    let firstName = cleaned.split(' ')[0] || 'Docente';
    firstName = firstName.charAt(0).toUpperCase() + firstName.slice(1);
    return `${firstName}1`;
}


