// ==========================================================================
// 🛡️ MOTOR DE SEGURIDAD EMPRESARIAL (ANTI-HACKEO, ANTI-XSS, ANTI-SQLi, BRUTE FORCE, CSRF & ROLE GUARDS)
// ==========================================================================
window.SecurityEngine = {
    // Sanitización estricta anti-XSS y anti-SQLi
    sanitizeInput(input) {
        if (typeof input !== 'string') return input;
        return input
            .replace(/&/g, '&amp;')
            .replace(/</g, '&lt;')
            .replace(/>/g, '&gt;')
            .replace(/"/g, '&quot;')
            .replace(/'/g, '&#x27;')
            .replace(/\//g, '&#x2F;')
            .replace(/script/gi, '')
            .replace(/javascript:/gi, '')
            .replace(/onerror=/gi, '')
            .replace(/onload=/gi, '')
            .replace(/eval\(/gi, '')
            .replace(/union\s+select/gi, '')
            .replace(/--/g, '');
    },

    sanitizeObject(obj) {
        if (!obj || typeof obj !== 'object') return obj;
        if (Array.isArray(obj)) {
            return obj.map(item => this.sanitizeObject(item));
        }
        const cleanObj = {};
        for (const key in obj) {
            if (Object.prototype.hasOwnProperty.call(obj, key)) {
                const val = obj[key];
                if (typeof val === 'string') {
                    cleanObj[key] = this.sanitizeInput(val);
                } else if (typeof val === 'object' && val !== null) {
                    cleanObj[key] = this.sanitizeObject(val);
                } else {
                    cleanObj[key] = val;
                }
            }
        }
        return cleanObj;
    },

    // Rate Limiting & Anti-Fuerza Bruta para login
    loginAttempts: {},
    checkLoginRateLimit(identifier) {
        const key = (identifier || 'unknown').toLowerCase().trim();
        const now = Date.now();
        const record = this.loginAttempts[key] || { count: 0, lockUntil: 0 };

        if (now < record.lockUntil) {
            const minutesLeft = Math.ceil((record.lockUntil - now) / 60000);
            return { allowed: false, message: `Cuenta temporalmente bloqueada por seguridad debido a múltiples intentos fallidos. Reintente en ${minutesLeft} minuto(s).` };
        }

        return { allowed: true };
    },

    recordFailedLogin(identifier) {
        const key = (identifier || 'unknown').toLowerCase().trim();
        const now = Date.now();
        const record = this.loginAttempts[key] || { count: 0, lockUntil: 0 };

        record.count += 1;
        if (record.count >= 5) {
            record.lockUntil = now + (5 * 60 * 1000); // 5 min
            record.count = 0;
            this.loginAttempts[key] = record;
            return `Demasiados intentos fallidos (5/5). Se activó el bloqueo anti-fuerza bruta por 5 minutos.`;
        }

        this.loginAttempts[key] = record;
        return `Credenciales incorrectas. Intentos fallidos: ${record.count}/5.`;
    },

    recordSuccessfulLogin(identifier) {
        const key = (identifier || 'unknown').toLowerCase().trim();
        delete this.loginAttempts[key];
        this.generateCSRFToken();
    },

    // Token CSRF por Sesión
    generateCSRFToken() {
        if (!sessionStorage.getItem('ENCC_CSRF_TOKEN')) {
            const array = new Uint8Array(24);
            window.crypto.getRandomValues(array);
            const token = Array.from(array, byte => byte.toString(16).padStart(2, '0')).join('');
            sessionStorage.setItem('ENCC_CSRF_TOKEN', token);
        }
        return sessionStorage.getItem('ENCC_CSRF_TOKEN');
    },

    // Guardias de Permisos por Rol en Tiempo de Ejecución (Protección de datos administrativos)
    enforceRolePermission(allowedRoles = []) {
        const currentRole = STATE.currentRole || 'docente';
        if (!allowedRoles.includes(currentRole) && currentRole !== 'admin') {
            showToast("Acceso Restringido: No tiene autorización suficiente para modificar estos datos.", "danger");
            console.warn(`[SEGURIDAD ENCCO] Intento no autorizado de acción por rol '${currentRole}'`);
            return false;
        }
        return true;
    },

    // Cierre de Sesión por Inactividad (30 min)
    inactivityTimer: null,
    initInactivityGuard() {
        const resetTimer = () => {
            if (this.inactivityTimer) clearTimeout(this.inactivityTimer);
            this.inactivityTimer = setTimeout(() => {
                if (STATE.isLoggedIn) {
                    showToast("Sesión suspendida por inactividad (30 min) para proteger sus datos.", "warning");
                    if (typeof logoutUser === 'function') logoutUser();
                }
            }, 30 * 60 * 1000);
        };

        ['mousemove', 'keydown', 'touchstart', 'scroll', 'click'].forEach(evt => {
            window.addEventListener(evt, resetTimer, { passive: true });
        });
        resetTimer();
    }
};

