function copyDatabaseSQL() {
    if (navigator.clipboard) {
        navigator.clipboard.writeText(DATABASE_SQL_SCRIPT).then(() => {
            showToast("¡Script SQL del modelo copiado al portapapeles con éxito!", "success");
        }).catch(() => {
            copyFallbackSQL();
        });
    } else {
        copyFallbackSQL();
    }
}

function copyFallbackSQL() {
    const textarea = document.createElement('textarea');
    textarea.value = DATABASE_SQL_SCRIPT;
    document.body.appendChild(textarea);
    textarea.select();
    document.execCommand('copy');
    document.body.removeChild(textarea);
    showToast("¡Script SQL del modelo copiado al portapapeles!", "success");
}

