function exportTeachersOfficialExcel() {
    try {
        const teachers = (STATE.users || []).filter(u => u.role === 'docente' || (u.id && String(u.id).startsWith('usr-doc-')));
        if (!teachers || teachers.length === 0) {
            showToast("No hay docentes registrados en el sistema para exportar.", "warning");
            return;
        }

        const cycle = STATE.activeCycle || '2026';
        const headers = [
            "No.", 
            "Nombre Completo del Catedrático", 
            "Renglón", 
            "Género", 
            "Correo Institucional", 
            "Contraseña", 
            "Especialidad / Título", 
            "Cátedras Asignadas", 
            "Estado"
        ];

        const dataRows = teachers.map((t, idx) => {
            const assignedClasses = (STATE.pensum || [])
                .filter(p => (p.teacherId && p.teacherId === t.id) || (p.teacher && p.teacher.toLowerCase() === (t.name || '').toLowerCase()))
                .map(p => `${p.subject || p.name} (${p.gradeCode || p.grade || ''})`)
                .join(', ');

            return [
                idx + 1,
                (t.name || '').toUpperCase(),
                t.renglon || '011',
                t.gender || 'Masculino',
                t.email || `${(t.username || 'docente')}@comercio.edu.gt`,
                t.password || 'C@rolina1',
                t.title || 'PEM / Catedrático Titular',
                assignedClasses || 'Sin asignaciones',
                t.active !== false ? 'Activo' : 'Inactivo'
            ];
        });

        const colWidths = [6, 35, 10, 12, 30, 15, 25, 40, 10];
        exportDataToExcelFile(`nomina_docentes_encc_${cycle}.xlsx`, "NÓMINA OFICIAL DE CATEDRÁTICOS Y CLAUSTRO DOCENTE", `CICLO LECTIVO ${cycle}`, headers, dataRows, colWidths);
    } catch (err) {
        console.error("Error al exportar docentes:", err);
        showToast("Error al exportar la nómina de docentes: " + err.message, "danger");
    }
}

