function renderSirePreview(subjectsList) {
    SIRE_PARSED_SUBJECTS_BUFFER = subjectsList;

    const previewContainer = document.getElementById('sirePreviewContainer');
    const tbody = document.getElementById('sirePreviewTableBody');
    const countSpan = document.getElementById('sirePreviewCount');
    const confirmBtn = document.getElementById('sireConfirmImportBtn');

    if (countSpan) countSpan.textContent = subjectsList.length;

    if (tbody) {
        tbody.innerHTML = subjectsList.map((s, idx) => `
            <tr>
                <td style="text-align:center; font-weight:700;">${idx + 1}</td>
                <td><code>${s.code}</code></td>
                <td><strong>${s.name}</strong></td>
                <td><span class="badge badge-info" style="font-size:0.75rem;">${s.grade}</span></td>
                <td><span class="badge badge-secondary" style="font-size:0.75rem;">${s.career}</span></td>
                <td style="text-align:center; font-weight:700;">${s.order || idx + 1}</td>
            </tr>
        `).join('');
    }

    if (previewContainer) previewContainer.style.display = 'block';
    if (confirmBtn) confirmBtn.disabled = false;

    showToast(`Se detectaron ${subjectsList.length} materias para importar. Revise la lista y confirme.`, 'info');
}

function executeSirePensumImport() {
    if (!checkSireImportPermissions()) return;
    if (!SIRE_PARSED_SUBJECTS_BUFFER || SIRE_PARSED_SUBJECTS_BUFFER.length === 0) {
        showToast('No hay materias cargadas para importar.', 'warning');
        return;
    }

    const importMode = document.querySelector('input[name="sireImportMode"]:checked')?.value || 'append';

    if (!Array.isArray(STATE.pensumCatalog)) STATE.pensumCatalog = [];

    // Si la carrera de la materia no existe en STATE.careers, agregarla automáticamente
    const existingCareers = (STATE.careers || []).map(c => c.name.toLowerCase());
    const newCareersToAdd = new Set();

    SIRE_PARSED_SUBJECTS_BUFFER.forEach(s => {
        if (s.career && !existingCareers.includes(s.career.toLowerCase())) {
            newCareersToAdd.add(s.career);
        }
    });

    newCareersToAdd.forEach(cName => {
        if (!STATE.careers) STATE.careers = [];
        STATE.careers.push({
            id: 'car-' + Date.now() + '-' + Math.floor(Math.random()*100),
            name: cName,
            code: cName.substring(0, 3).toUpperCase(),
            duration: '3 años',
            status: 'Activa'
        });
    });

    if (importMode === 'replace') {
        const importedCareers = [...new Set(SIRE_PARSED_SUBJECTS_BUFFER.map(s => s.career))];
        // Reemplazar solo las materias de las carreras importadas
        STATE.pensumCatalog = (STATE.pensumCatalog || []).filter(s => !importedCareers.includes(s.career));
        STATE.pensumCatalog.push(...SIRE_PARSED_SUBJECTS_BUFFER);
    } else {
        // Anexar evitando duplicados exactos (mismo nombre, grado y carrera)
        SIRE_PARSED_SUBJECTS_BUFFER.forEach(newSub => {
            const exists = STATE.pensumCatalog.some(existing => 
                existing.name.trim().toLowerCase() === newSub.name.trim().toLowerCase() &&
                existing.grade.trim().toLowerCase() === newSub.grade.trim().toLowerCase() &&
                existing.career.trim().toLowerCase() === newSub.career.trim().toLowerCase()
            );
            if (!exists) {
                STATE.pensumCatalog.push(newSub);
            }
        });
    }

    saveStateToLocalStorage();
    closeSirePensumImportModal();
    updateCareerSelects();
    updatePensumCatalogSelects();
    renderPensumCatalogTable();
    if (typeof renderDashboard === 'function') renderDashboard();

    showToast(`¡Pensum de SIRE / MINEDUC importado exitosamente! Total actual: ${(STATE.pensumCatalog || []).length} materias en catálogo.`, 'success');
}


function filterPensumCatalogTable(query = '') {
    renderPensumCatalogTable(query);
}

